'use strict';

// Prebuilt OpenVPN 2.7.5 binaries for win32-x64.
// Regenerated by scripts/fetch-openvpn-binaries.mjs; openvpn-binaries.json holds
// the pinned version and the expected file list.

const path = require('node:path');
const fs = require('node:fs');

const openvpnVersion = '2.7.5';

function binaryPath(name) {
  const candidate = path.join(__dirname, 'bin', name);
  if (!fs.existsSync(candidate)) {
    throw new Error(
      `${candidate} is not present. Reinstall @ovpn-sdk/openvpn-win32-x64 ` +
      `or run scripts/fetch-openvpn-binaries.mjs --platform win32-x64.`,
    );
  }
  return candidate;
}

module.exports = {
  openvpnVersion,
  openvpnPath: () => binaryPath('openvpn.exe'),
  tapctlPath: () => binaryPath('tapctl.exe'),
};
